import path from "node:path";

import type { ToolTable } from "../../contracts/config.ts";
import type { Wanted } from "../managed.ts";
import { GENERATED_PATH, PRESET_PATH, RUMDL_TABLE, standard } from "./paths.ts";

const PRESET_HEADER = [
  "# Managed by Cinch. Do not edit this file: `cinch doctor --fix` rewrites it.",
  `# To change a rule for this repository, set it under \`[tools.${RUMDL_TABLE}]\` in`,
  "# the Cinch config.",
  "",
  "",
].join("\n");

const GENERATED_HEADER = [
  `# Generated by Cinch from \`[tools.${RUMDL_TABLE}]\` in the Cinch config. Do not edit`,
  "# this file: `cinch doctor --fix` rewrites it.",
  "",
  "",
].join("\n");

/** The engine reads `extends` relative to the file that states it. */
const TO_PRESET = path.posix.relative(
  path.posix.dirname(GENERATED_PATH),
  PRESET_PATH
);

/** The copy of the standard. */
export const preset = async (): Promise<Wanted> => ({
  ok: true,
  text: `${PRESET_HEADER}${await standard()}`,
});

/**
 * The generated config: the line that extends the preset, then the
 * repository's table as it stands. Cinch does not read the table's keys,
 * with one exception: `extends` is the chain itself, so it cannot be set.
 */
export const generated = (table: ToolTable = {}): Promise<Wanted> => {
  if ("extends" in table) {
    return Promise.resolve({
      message: `\`[tools.${RUMDL_TABLE}]\` in the Cinch config sets \`extends\`, which Cinch writes itself. Remove that key.`,
      ok: false,
    });
  }
  const top = `${GENERATED_HEADER}extends = ${JSON.stringify(TO_PRESET)}\n`;
  if (Object.keys(table).length === 0) {
    return Promise.resolve({ ok: true, text: top });
  }
  try {
    const body = Bun.TOML.stringify(table).trimEnd();
    return Promise.resolve({ ok: true, text: `${top}\n${body}\n` });
  } catch (error) {
    const detail = error instanceof Error ? error.message : String(error);
    return Promise.resolve({
      message: `Cinch could not write \`[tools.${RUMDL_TABLE}]\` as TOML: ${detail}`,
      ok: false,
    });
  }
};
